const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Active users who signed up 6-8 days ago and have not been asked yet.
const form = norm($env.FEEDBACK_FORM_URL);
const from = norm($env.RESEND_FROM_EMAIL);
const eligible = [];
for (const l of $input.all().map((i) => i.json)) {
  if (norm(l.status).toLowerCase() !== 'active') continue;
  if (norm(l.feedback_requested_date)) continue;
  const email = norm(l.email).toLowerCase();
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  const d = daysSince(l.signup_date);
  if (!(d >= 6 && d <= 8)) continue;
  eligible.push({ l, email });
}
if (!eligible.length) return [];
if (!form || !from || !norm($env.RESEND_API_KEY)) {
  return [{ json: { send: false, alert: 'Feedback requests blocked: ' + eligible.length + ' eligible user(s). Set FEEDBACK_FORM_URL, RESEND_API_KEY and RESEND_FROM_EMAIL.' } }];
}
const reward = norm($env.FEEDBACK_REWARD_TEXT);
return eligible.slice(0, 50).map(({ l, email }) => ({ json: {
  send: true, lead_id: norm(l.lead_id), email_to: email,
  email_subject: 'Quick question (takes 30 seconds)',
  email_html: '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><h2>Hi ' + esc(l.name || 'there') + ',</h2><p>You have been on <strong>Eki</strong> for about a week. We would love your honest feedback - it helps us build a better product.</p><p style="text-align:center;margin:24px 0;"><a href="' + esc(form) + '" style="background:#6C63FF;color:#fff;padding:14px 32px;text-decoration:none;border-radius:8px;display:inline-block;">Share your feedback</a></p><p>It takes less than 30 seconds.</p>' + (reward ? '<p>' + esc(reward) + '</p>' : '') + '<p>The Eki Team</p></div>',
} }));

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const r = $input.first().json || {};
const src = $('Loop Over Requests').first(1).json;
const ok = !!r.id && !r.error;
// on failure nothing is marked, so the user is picked up again on the next daily run
return ok ? [{ json: { lead_id: src.lead_id, feedback_requested_date: nowIso().slice(0, 10) } }] : [{ json: { lead_id: '', skipped: true } }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const b = $input.first().json.body || {};
const email = norm(b.email).toLowerCase();
const rating = parseInt(b.rating, 10);
const errors = [];
if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('valid email is required');
if (Number.isNaN(rating) || rating < 1 || rating > 5) errors.push('rating must be an integer 1-5');
if (errors.length) return [{ json: { valid: false, errors } }];
const rec = b.would_recommend === true || ['true', 'yes', '1'].includes(norm(b.would_recommend).toLowerCase());
const today = nowIso().slice(0, 10);
return [{ json: { valid: true, fb: {
  feedback_id: 'F-' + Date.now(), email, user_role: norm(b.user_role), rating: String(rating), primary_value: norm(b.primary_value),
  pain_point: norm(b.pain_point), comments: norm(b.comments).slice(0, 2000), would_recommend: rec ? 'TRUE' : 'FALSE',
  submitted_date: today, action_taken: 'Pending Review', rating_category: rating >= 4 ? 'positive' : (rating === 3 ? 'neutral' : 'negative'),
} } }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fb = $('Validate Feedback').first().json.fb;
const cat = fb.rating_category;
const reward = norm($env.FEEDBACK_REWARD_TEXT);
const iosUrl = norm($env.APP_STORE_REVIEW_URL);
const androidUrl = norm($env.PLAY_STORE_REVIEW_URL);
let extra = '';
if (cat === 'positive' && (iosUrl || androidUrl)) {
  extra = '<p>If you have a minute, a store review helps other people find Eki:</p><ul>' + (iosUrl ? '<li><a href="' + esc(iosUrl) + '">Review on the App Store</a></li>' : '') + (androidUrl ? '<li><a href="' + esc(androidUrl) + '">Review on Google Play</a></li>' : '') + '</ul>';
}
const html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><h2>Thank you for your feedback</h2><p>We really appreciate you taking the time. Your input helps us improve Eki every day.</p>' + extra + (reward ? '<p>' + esc(reward) + '</p>' : '') + '<p>The Eki Team</p></div>';
const canEmail = !!norm($env.RESEND_API_KEY) && !!norm($env.RESEND_FROM_EMAIL);
return [{ json: {
  email_to: fb.email, email_subject: 'Thank you for your feedback', email_html: html, send_email: canEmail,
  is_negative: cat === 'negative',
  alert: 'Low feedback rating\nFrom: ' + fb.email + '\nRating: ' + fb.rating + '/5\nWould recommend: ' + (fb.would_recommend === 'TRUE' ? 'Yes' : 'No') + '\nComments: ' + (fb.comments || 'none'),
  received_date: fb.submitted_date, rating: fb.rating, response: { status: 'success', rating_category: cat },
} }];
